import inspect

def test_bind(cls, lock_file, timeout, mode, thread_local, blocking, is_singleton, **kwargs):
    all_params = {
        "lock_file": lock_file,
        "timeout": timeout,
        "mode": mode,
        "thread_local": thread_local,
        "blocking": blocking,
        "is_singleton": is_singleton,
        **kwargs,
    }
    sig = inspect.signature(cls.__init__)
    # filter all_params or pass positional / keyword args matching parameters
    params = sig.parameters
    init_params = {}

    # check if accepts **kwargs
    has_var_keyword = any(p.kind == inspect.Parameter.VAR_KEYWORD for p in params.values())

    if has_var_keyword:
        init_params = all_params
    else:
        # map first parameter if not named lock_file
        param_names = list(params.keys())[1:] # skip self
        # if the first parameter after self is not 'lock_file' (or present in all_params), but lock_file was passed positionally or as lock_file:
        if param_names and param_names[0] not in all_params and 'lock_file' in all_params:
            init_params[param_names[0]] = all_params['lock_file']

        for k, v in all_params.items():
            if k in params:
                init_params[k] = v

    bound = sig.bind(None, **init_params)
    print("bound:", bound.arguments)

