def get_init_params(cls, all_params):
    sig = inspect.signature(cls.__init__)
    params = sig.parameters
    has_var_keyword = any(p.kind == inspect.Parameter.VAR_KEYWORD for p in params.values())
    if has_var_keyword:
        return all_params

    init_params = {}
    param_names = [name for name, p in params.items() if name != "self" and p.kind in (inspect.Parameter.POSITIONAL_ONLY, inspect.Parameter.POSITIONAL_OR_KEYWORD, inspect.Parameter.KEYWORD_ONLY)]

    # If the first non-self parameter is not in all_params, but 'lock_file' is in all_params, map 'lock_file' to it.
    if param_names and param_names[0] not in all_params and "lock_file" in all_params:
        init_params[param_names[0]] = all_params["lock_file"]

    for k, v in all_params.items():
        if k in params:
            init_params[k] = v

    return init_params

